using System.IO;
using UnityEditor;
using UnityEngine;

namespace ModernDrone.Editor
{
    /// <summary>
    /// Terrain data (Assets/_Project/Scenes/*_Terrain.asset, ~66 MB each) is generated by the scene builders and is not
    /// kept in git: every rebuild rewrote all nine and pushed ~620 MB of Git LFS. On a fresh clone the scenes reference
    /// terrains that do not exist yet, so the first time the editor opens the project it runs Rebuild Everything.
    /// Skipped in batch mode (tests, builds on CI); Modern Drone/Setup/Rebuild Everything does the same by hand.
    /// </summary>
    [InitializeOnLoad]
    static class TerrainBootstrap
    {
        const string ScenesDir = "Assets/_Project/Scenes";
        const string SessionKey = "ModernDrone.TerrainBootstrap.Checked";

        static TerrainBootstrap()
        {
            if (Application.isBatchMode || SessionState.GetBool(SessionKey, false)) return;
            EditorApplication.delayCall += Check;
        }

        /// <summary>Scenes whose terrain asset is missing: every mission / proving-ground scene has one next to it.</summary>
        static string[] MissingTerrains()
        {
            var missing = new System.Collections.Generic.List<string>();
            if (!Directory.Exists(ScenesDir)) return missing.ToArray();
            foreach (var scene in Directory.GetFiles(ScenesDir, "*.unity"))
            {
                string name = Path.GetFileNameWithoutExtension(scene);
                if (!name.StartsWith("Mission_") && name != "ProvingGround") continue;
                if (!File.Exists(Path.Combine(ScenesDir, name + "_Terrain.asset"))) missing.Add(name);
            }
            return missing.ToArray();
        }

        static void Check()
        {
            SessionState.SetBool(SessionKey, true);
            if (EditorApplication.isPlayingOrWillChangePlaymode || EditorApplication.isCompiling) return;
            var missing = MissingTerrains();
            if (missing.Length == 0) return;
            Debug.Log($"[ModernDrone] Terrain data missing for {string.Join(", ", missing)} (it is generated, not in git): rebuilding all scenes.");
            EditorUtility.DisplayProgressBar("Modern Drone", "Generating terrains and scenes (first open, a few minutes)...", 0.5f);
            try
            {
                MainMenuSceneBuilder.RebuildAll();
            }
            finally
            {
                EditorUtility.ClearProgressBar();
            }
        }
    }
}
